#include <stdio.h>
#include <stdlib.h>

int *read_array(int n) {
    int *a = malloc((size_t)n * sizeof *a);
    if (a == NULL) {
        return NULL;
    }
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    return a;
}

int main(void) {
    int n;
    scanf("%d", &n);
    int *t = read_array(n);
    if (t == NULL) {
        return 1;
    }
    int rises = 0, best = 0;
    for (int i = 0; i < n; i++) {
        int delta = t[i + 1] - t[i];
        if (delta > 0) {
            rises++;
            if (delta > best) {
                best = delta;
            }
        }
    }
    printf("rises=%d max=%d\n", rises, best);
    free(t);
    return 0;
}

