    int n;
    scanf("%d", &n);
    int *a = read_array(n);
    long long *prefix = malloc((size_t)n * sizeof *prefix);
    if (a == NULL || prefix == NULL) {
        free(a);
        free(prefix);
        return 1;
    }
    for (int i = 0; i < n; i++) {
        prefix[i] = prefix[i - 1] + a[i];
    }
    int q;
    scanf("%d", &q);
    for (int k = 0; k < q; k++) {
        int l, r;
        scanf("%d %d", &l, &r);
        printf("%lld\n", prefix[r] - prefix[l - 1]);
    }
    free(a);
    free(prefix);
    return 0;
}

