#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int rows, cols;
    scanf("%d %d", &rows, &cols);
    int *t = calloc((size_t)rows * cols, sizeof *t);
    if (t == NULL) {
        return 1;
    }
    char cmd[8];
    while (scanf("%7s", cmd) == 1) {
        if (strcmp(cmd, "set") == 0 || strcmp(cmd, "get") == 0) {
            int r, c, v = 0;
            scanf("%d %d", &r, &c);
            if (cmd[0] == 's') {
                scanf("%d", &v);
            }
            if (r < 0 || r >= rows || c < 0 || c >= cols) {
                printf("error\n");
            } else if (cmd[0] == 's') {
                t[r * cols + c] = v;
            } else {
                printf("%d\n", t[r * cols + c]);
            }
        } else {
            int k;
            scanf("%d", &k);
            int is_row = strcmp(cmd, "row") == 0;
            int limit = is_row ? rows : cols;
            if (k < 0 || k >= limit) {
                printf("error\n");
                continue;
            }
            long long sum = 0;
            if (is_row) {
                for (int c = 0; c < cols; c++) {
                    sum += t[k * cols + c];
                }
            } else {
                for (int r = 0; r < rows; r++) {
                    sum += t[r * cols + k];
                }
            }
            printf("%lld\n", sum);
        }
    }
    free(t);
    return 0;
}

